window.kbPageData["views/entry/k-9a00bd0185c0ac82"] = {"key":"entry/k-9a00bd0185c0ac82","state":{"route":"entry/k-9a00bd0185c0ac82"},"node":{"id":"k-9a00bd0185c0ac82","mode":"k","title":"自由贸易试验区提升战略","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#13","国考 2024 行政执法 行测#7"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["open"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["经济"],"来源主题":["年度政府工作"],"资料类别":["政治理论专项","时政"]},"directorySummary":"自由贸易试验区提升战略是党的二十大报告提出的开放部署，要求在现有自由贸易试验区基础上扩大开放、深化制度创新，建设更高水平的自由贸易试验区。","review":{"title":"自由贸易试验区提升战略","type":"制度与规则","definition":"自由贸易试验区提升战略是党的二十大报告提出的开放部署，要求在现有自由贸易试验区基础上扩大开放、深化制度创新，建设更高水平的自由贸易试验区。","explanation":"2023年关于深入推进自由贸易试验区建设的重要指示提出，坚持党的全面领导，以高水平开放为引领、以制度创新为核心，统筹发展和安全，高标准对接国际经贸规则，深入推进制度型开放，发挥自贸试验区的示范作用。","basis":"据关联原题及所列出处编释。","references":[{"source":"open","location":"自贸试验区建设十周年指示"}],"related":["k-250dc0a204f29da1","k-0b56b67d9fed06b6","k-f65c4b65787428bd"],"domain":"经济","examFocus":{"政治理论必刷100题#13":"核对自由贸易试验区建设中引领方向、创新重点和经贸规则对接的要求，分清各项表述的作用。","国考 2024 行政执法 行测#7":"核对党的二十大报告的贸易投资开放部署，区分外资准入、区域开放布局和自贸区建设各项措施所针对的对象。"}},"aspects":[{"title":"自贸试验区建设的引领与核心","uses":[{"unit":"Q1","role":"解题依据","use":"本题的⑤对应2023年关于深入推进自由贸易试验区建设的重要指示。⑤保留了高水平开放引领和高标准对接国际经贸规则的要求，但将核心写成“技术创新”，因此该项错误。","evidence":"坚持以高水平开放为引领、以制度创新为核心","qids":["政治理论必刷100题#13"]}]},{"title":"党的二十大报告的开放部署","uses":[{"unit":"Q2","role":"直接考查","use":"本题的④对应党的二十大报告并列提出的两项部署，即实施自由贸易试验区提升战略、扩大面向全球的高标准自由贸易区网络。④与货物贸易、服务贸易和数字贸易措施所在的①均正确，选C。","evidence":"实施自由贸易试验区提升战略，扩大面向全球的高标准自由贸易区网络","qids":["国考 2024 行政执法 行测#7"]}]}],"sources":[{"id":"8e5b8d0370bf2daa","label":"自由贸易试验区提升战略","topic":"年度政府工作","category":"时政","text":"4.自由贸易试验区提升战略\n实施自由贸易试验区提升战略是推进高水平对外开放、推动高质量发展的重要举措。要\n坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届二中、三\n中全会精神，完整准确全面贯彻新发展理念，构建新发展格局，坚持党的全面领导，坚持以\n高水平开放为引领、以制度创新为核心，坚持统筹发展和安全，主动对接国际高标准经贸\n规则，稳步扩大规则、规制、管理、标准等制度型开放，加强改革整体谋划和系统集成，推\n动全产业链创新发展，将自由贸易试验区建设成为畅通国内国际双循环的重要枢纽、推动\n高质量发展的强劲引擎，在进一步全面深化改革、推进中国式现代化进程中更好发挥示范作\n用。\n经过 5 年左右的首创性、集成式探索，实现自由贸易试验区制度型开放水平、系统性改\n革成效、开放型经济质量全面提升，以贸易、投资、资金流动、交通运输、人员往来自由便\n利和数据安全有序流动为重点的政策体系更加完善，科技创新和产业创新深度融合，现代产\n业集群能级跃升，新质生产力加快发展，打造开放层次更高、营商环境更优、辐射作用更\n强的改革开放新高地。\n——《关于实施自由贸易试验区提升战略的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":8,"last":8,"page":8,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#13":{"paper":"政治理论必刷100题","n":13,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",4],"asrc":["国省考政治理论必刷100题.pdf",38],"card":"b884ac860eead3b19930e136","links":[{"id":"k-9a00bd0185c0ac82","role":"解题依据","why":"自贸试验区建设要求以制度创新为核心，并高标准对接国际经贸规则。"}]},"国考 2024 行政执法 行测#7":{"paper":"国考 2024 行政执法 行测","n":7,"mod":"常识判断","src":["dfddc59dc6e7d9da5d71.pdf",2],"asrc":["6493f3a6a55c38431852.pdf",3],"card":"a4b4ab30129d7091ad26dae8","links":[{"id":"k-9a00bd0185c0ac82","role":"直接考查","why":"题目直接核对自由贸易试验区提升战略及高标准自由贸易区网络的部署。"}]}},"terms":{"k-250dc0a204f29da1":{"id":"k-250dc0a204f29da1","mode":"k","type":"事实与事件","title":"利用外资法规政策体系和工作体系","qs":[],"count":2},"k-0b56b67d9fed06b6":{"id":"k-0b56b67d9fed06b6","mode":"k","type":"制度与规则","title":"自贸试验区建设中的制度创新","qs":[],"count":2},"k-f65c4b65787428bd":{"id":"k-f65c4b65787428bd","mode":"k","type":"事实与事件","title":"自贸试验区自由贸易账户试点","qs":[],"count":2}},"references":{"open":{"name":"关于深入推进自由贸易试验区建设的重要指示（2023年）","url":"https://www.cac.gov.cn/2023-09/26/c_1697388450748059.htm"}},"topics":[{"slug":"open","title":"高水平开放与经贸规则"}],"units":{"k-9a00bd0185c0ac82":[["政治理论必刷100题#13"],["国考 2024 行政执法 行测#7"]]}};
